(* [comment removed for export] *)
Definition aos_segA_post (sp gp tp t0 t1 t2 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32)
    (ioc ownp allocb lo : Z) (ra s0 s1 s2 : word) (m : mem) : machine_state -> Prop :=
  fun ms' => exists a3 m',
    ms' = MS (mkR (Z_to_bv 64 P_AOS_RET1) (Z_to_bv 64 (bv_unsigned sp + -32)) gp tp t0 t1 t2
                  (Z_to_bv 64 allocb) (Z_to_bv 64 ownp) (Z_to_bv 64 allocb) (Z_to_bv 64 272) (Z_to_bv 64 8) a3 a4 a5 a6 a7
                  (Z_to_bv 64 ioc) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 P_ALLOCIMPL_ALLOCATE) fc None m' (seg_rom rsegs)
    /\ munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp + -32)
    /\ rw_cells rsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra].

Lemma aos_segA : forall ra sp gp tp t0 t1 t2 s0 s1 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem) (AT ioc ownp allocb lo : Z) (jal : list byte),
  ro_cells rsegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= 2^64 ->
  rw_cells rsegs m allocb [C8 (wz VP_ALLOCIMPL); CB 8 jal] -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp) -> lo + 32 <= bv_unsigned sp -> hceil <= lo ->
  allocb + SZ_ALLOCIMPL <= lo -> 0 <= ownp < 2^64 -> 0 <= ioc < 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (aos_segA_post sp gp tp t0 t1 t2 a4 a5 a6 a7 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc ioc ownp allocb lo ra s0 s1 s2 m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 AT) (Z_to_bv 64 ioc) (Z_to_bv 64 ownp) a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
