(* [comment removed for export] *)
Definition mss_W (lo : Z) (sp : word) (S r : Z) : list (Z * Z) := [(lo, bv_unsigned sp); (S, S + 48); (r, r + SZ_REG)]%Z.

Definition mss_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (LB : list block) (S r ioc cfgb lo : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom rsegs)
    /\ munch (mss_W lo sp S r) m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ stk rsegs m' lo (bv_unsigned sp)
    /\ rw_cells rsegs m' S (SvcHdrCells (sched_hdr ioc cfgb))
    /\ Registry LB m' r ioc S 0.

Lemma mss_segB : forall (S r ioc cfgb lo : Z) (LB : list block)
    sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 (ra s0 s1 s0x : word)
    (F : bvmap 5 word) fc (m : mem) (j0 j16 : list byte) (wA : word),
  rw_cells rsegs m (bv_unsigned sp + -48) [CB 8 j0] ->
  rw_cells rsegs m (bv_unsigned sp + -40) [C8 wA; CB 8 j16] ->
  rw_cells rsegs m (bv_unsigned sp + -24) [C8 s1; C8 s0; C8 ra] ->
  rw_cells rsegs m S (SvcHdrCells (sched_hdr0 ioc)) ->
  Registry LB m r ioc cfgb 0 -> ConfigSvc LB m cfgb (cfg_hdr ioc) -> XStatics m ->
  stk rsegs m lo (bv_unsigned sp + -48) -> lo + 48 + DAS_STACK <= bv_unsigned sp -> hceil <= lo ->
  r + NEWSZ_REG <= lo -> (r + SZ_REG <= 0x10000 \/ 0xb4000 <= r) ->
  S + NEWSZ_SCH <= lo -> (S + NEWSZ_SCH <= 0x10000 \/ 0xb4000 <= S) -> 0 < S ->
  cfgb + NEWSZ_CFG <= lo -> 0 < cfgb -> (cfgb + NEWSZ_CFG <= 0x10000 \/ 0xb4000 <= cfgb) ->
  (r + NEWSZ_REG <= S \/ S + NEWSZ_SCH <= r) -> (cfgb + NEWSZ_CFG <= r \/ r + NEWSZ_REG <= cfgb) -> (S + NEWSZ_SCH <= cfgb \/ cfgb + NEWSZ_CFG <= S) ->
  0 <= ioc < 2^64 ->
  bv_unsigned ra mod 2 = 0 ->
  mem_inv rsegs m ->
  evt rsegs (mss_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc LB S r ioc cfgb lo m)
    (MS (mkR (Z_to_bv 64 P_MSS_RET1) (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2
             s0x (Z_to_bv 64 r) (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
