Section W.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.
  Hypothesis RHEAP_canary : forall s LB m, hs_RHEAP H s LB m -> CanaryReads m.

  (* [comment removed for export] *)
  Definition alloc_obj_sched_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (ioc regb cfgb allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (p : bptr) (S : Z) j7,
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ hs_rauxv_ok H m' B
      /\ rblock_range S NEWSZ_SCH /\ hs_RHEAP H s' ((p, S, NEWSZ_SCH) :: LB) m'
      /\ SchedCells m' S ioc /\ rw_cells rsegs m' (S + SZ_SCH) (CookieCells j7)
      /\ sc_inv ((p, S, NEWSZ_SCH) :: LB) m' ioc regb cfgb tp (wz 0)
      /\ AllocImpl ((p, S, NEWSZ_SCH) :: LB) m' allocb
      /\ xpres LB (bv_unsigned sp) [(regb + O_REG_MUTEX, regb + O_REG_MUTEX + 40)] m m'.

  Definition alloc_obj_sched_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (AT ioc ownp regb cfgb allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 AT -> a1 = Z_to_bv 64 ioc -> a2 = Z_to_bv 64 ownp ->
      F = bvmap_empty -> fc = Z_to_bv 32 0 ->
      ro_cells rsegs m AT [C8 (wz allocb)] -> bv_unsigned sp <= AT -> AT + 8 <= 2^64 ->
      ro_cells rsegs m ownp [CB 1 [b8 0]] -> bv_unsigned sp <= ownp -> ownp + 1 <= 2^64 ->
      bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 ->
      sc_inv LB m ioc regb cfgb tp errv -> AllocImpl LB m allocb ->
      (cfgb + NEWSZ_CFG <= regb \/ regb + NEWSZ_REG <= cfgb) ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_SCH <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffff ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - ALLOC_OBJ_SCHED_STACK ->
      mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
