  (* [comment removed for export] *)
  Definition make_svc_sched_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
      (s : PState) (LB : list block) (regb ioc cfgb allocb lo B : Z) (m : mem) (mo : Model) : config -> Prop :=
    fun c => exists t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' (s' : PState) (p : bptr) (S : Z),
      cfg_ms c = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 S) a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                    F (ret_pc ra) fc None m' (seg_rom rsegs)
      /\ hs_KREL H s' (cfg_model c) /\ hs_MPRES H mo (cfg_model c)
      /\ mem_inv rsegs m' /\ stk rsegs m' lo (bv_unsigned sp)
      /\ rw_cells rsegs m' (bv_unsigned tp + -164) [C4 (wz 0)] /\ hs_rauxv_ok H m' B
      /\ rblock_range S NEWSZ_SCH /\ hs_RHEAP H s' ((p, S, NEWSZ_SCH) :: LB) m'
      /\ Scheduler ((p, S, NEWSZ_SCH) :: LB) m' S (mkSCH (sched_hdr ioc cfgb) 0 0 0)
      /\ Registry ((p, S, NEWSZ_SCH) :: LB) m' regb ioc S 0
      /\ ConfigSvc ((p, S, NEWSZ_SCH) :: LB) m' cfgb (cfg_hdr ioc)
      /\ AllocImpl ((p, S, NEWSZ_SCH) :: LB) m' allocb
      /\ XStatics m' /\ CanaryReads m'
      /\ xpres LB (bv_unsigned sp) [(regb, regb + NEWSZ_REG)] m m'.

  Definition make_svc_sched_stmt : Prop :=
    forall (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
           (F : bvmap 5 word) (fc : bv 32) (m : mem) (mo : Model)
           (s : PState) (LB : list block) (regb ownp ioc cfgb allocb lo B : Z) (errv : word),
      a0 = Z_to_bv 64 regb -> a1 = Z_to_bv 64 ownp ->
      F = bvmap_empty -> fc = Z_to_bv 32 0 ->
      ro_cells rsegs m ownp [CB 1 [b8 0]] -> bv_unsigned sp <= ownp -> ownp + 1 <= 2^64 ->
      ro_cells rsegs m ioc [C8 (wz allocb)] -> bv_unsigned sp <= ioc -> ioc + 24 <= 2^64 ->
      sc_inv LB m ioc regb cfgb tp errv -> AllocImpl LB m allocb ->
      hs_RHEAP H s LB m -> hs_KREL H s mo ->
      lb_bytes LB + NEWSZ_SCH <= hs_LIVE_MAX H -> Z.of_nat (length LB) + 1 <= hs_LIVE_CNT_MAX H ->
      hs_rauxv_ok H m B -> bv_unsigned sp <= B ->
      bv_unsigned sp mod 16 = 0 -> bv_unsigned sp <= 0x7fffffffffff ->
      stk rsegs m lo (bv_unsigned sp) -> hceil <= lo -> lo <= bv_unsigned sp - MAKE_SVC_SCHED_STACK ->
      mem_inv rsegs m -> tp = Z_to_bv 64 RATP ->
      bv_unsigned ra mod 2 = 0 ->
      hs_SR H (make_svc_sched_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB regb ioc cfgb allocb lo B m mo)
        (mkCfg (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                   F (Z_to_bv 64 P_MAKE_SVC_SCHED) fc None m (seg_rom rsegs)) mo).

  Lemma make_svc_sched_spec : make_svc_sched_stmt.
